import pathlib,base64,subprocess,sys
root=pathlib.Path('/content/min-tokens');root.mkdir(exist_ok=True)
files={'prepare.py': '', 'requirements.txt': '', 'baseline_min_new_tokens.py': '', 'pr_min_new_tokens.py': '', 'min_new_tokens_kernel.py': '', 'test_penaltylib.py': '', 'test_min_new_tokens.py': '', 'bench.py': '', 'gpu-correctness.py': '', 'final-tests.py': '', 'e2e-final.py': '', 'e2e-high.py': '', 'run-final.py': '', 'run-high.py': '', 'start-experiment.py': '', 'collect.py': '', 'control.py': '', 'control-launcher.py': ''}
for n,data in files.items():(root/n).write_bytes(base64.b64decode(data))
p=subprocess.Popen([sys.executable,str(root/'prepare.py')],stdout=open(root/'prepare.log','w'),stderr=subprocess.STDOUT,stdin=subprocess.DEVNULL,start_new_session=True)
(root/'worker.pid').write_text(str(p.pid));print('PREPARE_STARTED',p.pid)
